// Determine what content to generate today
const scheduledContent = $('Fetch Today Scheduled Content').all() || [];
const activeCampaigns = $('Fetch Active Campaigns').all() || [];
const dayOfWeek = new Date().getDay(); // 0=Sun, 1=Mon, ...

// Content calendar template per day
const dailyContentPlan = {
  1: { platforms: ['meta', 'linkedin'], types: ['educational', 'tip'] },        // Monday
  2: { platforms: ['meta', 'tiktok'], types: ['behind_scenes', 'story'] },       // Tuesday
  3: { platforms: ['meta', 'linkedin', 'tiktok'], types: ['value', 'carousel'] },// Wednesday
  4: { platforms: ['meta', 'tiktok'], types: ['engagement', 'poll'] },           // Thursday
  5: { platforms: ['meta', 'tiktok', 'linkedin'], types: ['promo', 'cta'] },     // Friday
  6: { platforms: ['meta', 'tiktok'], types: ['lifestyle', 'fun'] },             // Saturday
  0: { platforms: ['meta'], types: ['motivation', 'recap'] }                     // Sunday
};

const todayPlan = dailyContentPlan[dayOfWeek] || dailyContentPlan[1];

return {
  json: {
    date: new Date().toISOString().split('T')[0],
    day_of_week: dayOfWeek,
    scheduled_count: scheduledContent.length,
    active_campaigns: activeCampaigns.map(c => c.json),
    platforms: todayPlan.platforms,
    content_types: todayPlan.types,
    brand_voice: $env.BRAND_VOICE || 'professionnel mais accessible, inspire confiance',
    business_niche: $env.BUSINESS_NICHE || 'marketing digital'
  }
};

