// Parse AI response and create individual post items
const aiResponse = $input.item.json.message.content;
let posts;
try {
  const parsed = JSON.parse(aiResponse);
  posts = parsed.posts || [parsed];
} catch (e) {
  posts = [{ error: 'Parse failed', raw: aiResponse }];
}

// Return each post as separate item for batch processing
return posts.map(post => ({
  json: {
    ...post,
    date: $('Plan Today Content').item.json.date,
    agent_id: 'content-creator',
    workflow_id: 'WF-CONTENT-SOCIAL',
    status: 'draft'
  }
}));
